// Validate the shared credential and the required fields, then mint a demo ticket.
// The secret is read from an n8n environment variable so it is never in this export.
const expected = $env.PROTOTYPE_SECRET || '';
const headers = $input.first().json.headers || {};
const provided = headers['x-prototype-secret'] || headers['X-Prototype-Secret'] || '';

if (expected && provided !== expected) {
  return [{ json: { _ok: false, _code: 401, error: 'bad or missing shared secret' } }];
}

const body = $input.first().json.body || {};
const required = ['request_id', 'call_id', 'unit', 'issue', 'source'];
const missing = required.filter((f) => !body[f]);
if (missing.length) {
  return [{ json: { _ok: false, _code: 400, error: 'missing fields: ' + missing.join(', ') } }];
}

// Deterministic from request_id, so the same request maps to the same ticket if the
// backend ever re-sends it. This is a demo ticket: no person is notified.
let hash = 0;
for (const ch of String(body.request_id)) {
  hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
}
const ticket = 'DEMO-' + hash.toString(36).toUpperCase().slice(0, 6).padStart(6, '0');

return [{ json: {
  _ok: true,
  _code: 200,
  status: 'accepted',
  ticket_id: ticket,
  request_id: body.request_id,
  received: { unit: body.unit, issue: body.issue, call_id: body.call_id, source: body.source }
} }];
